void mainGameLoop(void) {
    while (*(int *)(0x00405700 + 12) == 0) {
        aliensMove();
        aliensMissileMove();
        playerMissileMove();
        bunkersDisplay();
        checkWaveClear();
    }
}

void render(void) {
    int *alienBlock = (int *)0x00405100;
    int *lowest_ship = (int *)0x00405380;
    for (int k = 0; k < 10; k++) lowest_ship[k] = -1;
    int count = 0;
    for (int r = 0; r < 5; r++) {
        for (int c = 0; c < 10; c++) {
            if (alienBlock[r * 10 + c] != 0) {
                lowest_ship[c] = r;
                count++;
            }
        }
    }
    *(int *)(0x00405520 + 24) = count;
    aliensRefresh();
}

