int bunkersHitCheck(int shotx, int shoty) {
    if (shoty < 18 || shoty >= 22) return 0;
    if (shotx < 0 || shotx >= 80) return 0;
    int *bunker = (int *)0x00405240;
    int row = shoty - 18;
    int col = shotx;
    if (bunker[row * 81 + col] == 1) {
        bunkersErodeBlock(row, col);
        return 1;
    }
    return 0;
}

void bunkersErodeBlock(int row, int col) {
    int *bunker = (int *)0x00405240;
    bunker[row * 81 + col] = 0;
}

void playerMoveLeft(void) {
    if (*(int *)(0x00405600 + 0) > 4) {
        *(int *)(0x00405600 + 0) -= 2;
    }
}

void playerMoveRight(void) {
    if (*(int *)(0x00405600 + 0) < 72) {
        *(int *)(0x00405600 + 0) += 2;
    }
}

void playerFireMissile(void) {
    int px = *(int *)(0x00405600 + 0);
    playerMissileSpawn(px + 1, 21);
}

void playerMissileSpawn(int x, int y) {
    int *pm = (int *)0x00405480;
    if (pm[0] == 0) {
        pm[0] = x;
        pm[1] = y;
    }
}

void playerMissileMove(void) {
    int *pm = (int *)0x00405480;
    if (pm[0] != 0) {
        pm[1] -= 1;
        if (bunkersHitCheck(pm[0], pm[1])) {
            pm[0] = 0;
        } else if (alienHitCheck(pm[0], pm[1])) {
            pm[0] = 0;
        } else if (pm[1] <= 1) {
            pm[0] = 0;
        }
    }
}

int alienHitCheck(int px, int py) {
    int ax = *(int *)(0x00405520 + 0);
    int ay = *(int *)(0x00405520 + 4);
    int *alienBlock = (int *)0x00405100;
    if (py >= ay && py < ay + 10) {
        int r = (py - ay) / 2;
        int c = (px - ax) / 4;
        if (r >= 0 && r < 5 && c >= 0 && c < 10 && alienBlock[r * 10 + c] != 0) {
            int type = alienBlock[r * 10 + c];
            alienBlock[r * 10 + c] = 0;
            doScoring(type);
            return 1;
        }
    }
    return 0;
}

int aliensMissileMove(void) {
    int *missiles = (int *)0x00405400;
    int fPlayerHit = 0;
    for (int i = 0; i < 5; i++) {
        int sx = missiles[i * 2];
        int sy = missiles[i * 2 + 1];
        if (sx != 0) {
            if (bunkersHitCheck(sx, sy) == 1) {
                missiles[i * 2] = 0;
                continue;
            }
            sy++;
            missiles[i * 2 + 1] = sy;
            if (playerHitCheck(sx, sy) == 1) {
                missiles[i * 2] = 0;
                fPlayerHit = 1;
            } else if (sy >= 24) {
                missiles[i * 2] = 0;
            }
        }
    }
    return fPlayerHit;
}

int playerHitCheck(int shotx, int shoty) {
    int px = *(int *)(0x00405600 + 0);
    int py = *(int *)(0x00405600 + 4);
    if (shoty == py && shotx >= px && shotx <= px + 3) {
        playerExplosion();
        return 1;
    }
    return 0;
}

void playerExplosion(void) {
    *(int *)(0x00405600 + 8) -= 1; // lives--
    *(int *)(0x00405600 + 12) = 1; // status = EXPLODING
    if (*(int *)(0x00405600 + 8) <= 0) {
        *(int *)(0x00405700 + 12) = 1; // is_game_over = 1
    }
}

void doScoring(int alien_type) {
    int points = (alien_type == 1) ? 30 : ((alien_type == 2) ? 20 : 10);
    *(int *)(0x00405700 + 0) += points;
    updateHighScore();
}

void checkWaveClear(void) {
    if (*(int *)(0x00405520 + 24) == 0) {
        *(int *)(0x00405700 + 8) += 1; // level++
        aliensReset();
        bunkersReset();
    }
}
